const config = $('Load AI Agent Configuration').first().json.agentConfig;
const existingUsers = $('Get Existing Kanboard Users').first().json.result || [];
const existingProjects = $('Get Existing Kanboard Projects').first().json.result || [];

console.log(`📊 Analysis starting...`);
console.log(`Found ${existingUsers.length} existing users`);
console.log(`Found ${existingProjects.length} existing projects`);

// Create maps for quick lookup
const userMap = new Map(existingUsers.map(u => [u.username, u]));
const projectMap = new Map(existingProjects.map(p => [p.name, p]));

const actions = {
  projectsToCreate: [],
  agentsToCreate: [],
  existingAgents: [],
  stats: {
    totalDepartments: Object.keys(config).length,
    totalAgents: Object.values(config).reduce((sum, dept) => sum + dept.agents.length, 0),
    existingUsers: existingUsers.length,
    existingProjects: existingProjects.length
  }
};

// Generate secure password function
const generatePassword = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
  let password = '';
  for (let i = 0; i < 16; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return password + 'Ai1!';
};

// Check each department
Object.entries(config).forEach(([deptName, deptConfig]) => {
  console.log(`🔍 Checking department: ${deptName}`);

  // Check if project exists
  if (!projectMap.has(deptConfig.projectName)) {
    console.log(`   📋 Project needs creation: ${deptConfig.projectName}`);
    actions.projectsToCreate.push({
      department: deptName,
      projectName: deptConfig.projectName,
      description: deptConfig.description,
      color: deptConfig.color
    });
  } else {
    console.log(`   ✅ Project exists: ${deptConfig.projectName}`);
  }

  // Check each agent in department
  deptConfig.agents.forEach(agent => {
    if (!userMap.has(agent.username)) {
      console.log(`   🤖 Agent needs creation: ${agent.name} (${agent.username})`);
      actions.agentsToCreate.push({
        ...agent,
        department: deptName,
        projectName: deptConfig.projectName,
        password: generatePassword(),
        needsUser: true,
        needsProjectAssignment: true
      });
    } else {
      console.log(`   ✅ Agent exists: ${agent.name}`);
      actions.existingAgents.push({
        ...agent,
        department: deptName,
        kanboardId: userMap.get(agent.username).id
      });
    }
  });
});

console.log(`📋 Summary:`);
console.log(`   Projects to create: ${actions.projectsToCreate.length}`);
console.log(`   Agents to create: ${actions.agentsToCreate.length}`);
console.log(`   Existing agents: ${actions.existingAgents.length}`);

return [{ json: { actions } }];"
